129	namespace {
130	bool aclshmemi_parse_port_strict(const std::string& port_str, uint16_t& port)
131	{
132	    constexpr int max_port = 65535;
133	    try {
134	        size_t parsed_len = 0;
135	        int port_int = std::stoi(port_str, &parsed_len);
136	        if (parsed_len != port_str.size() || port_int < 0 || port_int > max_port) {
137	            return false;
138	        }
139	        port = static_cast<uint16_t>(port_int);
140	        return true;
141	    } catch (const std::exception&) {
142	        return false;
143	    }
144	}
