146	
147	int32_t version_compatible()
148	{
149	    int32_t status = ACLSHMEM_SUCCESS;
150	    return status;
151	}
152	
153	int32_t aclshmemi_state_init_attr(aclshmemx_init_attr_t* attributes, uint64_t heap_size)
154	{
155	    int32_t status = ACLSHMEM_SUCCESS;
156	    g_state.mype = attributes->my_pe;
157	    g_state.npes = attributes->n_pes;
158	    g_state.heap_size = heap_size;
159	
160	    aclrtStream stream = nullptr;
161	    ACLSHMEM_CHECK_RET(aclrtCreateStream(&stream));
162	    g_state_host.default_stream = stream;
163	    g_state_host.default_event_id = DEFAULT_TEVENT;
164	    g_state_host.default_block_num = DEFAULT_BLOCK_NUM;
165	    return status;
166	}
167	
168	bool is_valid_data_op_engine_type(data_op_engine_type_t value)
169	{
170	    constexpr uint32_t valid_mask = (static_cast<uint32_t>(ACLSHMEM_DATA_OP_MAX) << 1) - 1;
171	    uint32_t int_value = static_cast<uint32_t>(value);
172	    return int_value > 0 && (int_value & ~valid_mask) == 0;
173	}
174	
175	bool aclshmemi_user_buffer_heap_engine_supported(data_op_engine_type_t engine)
176	{
177	    constexpr uint32_t mte_engine = static_cast<uint32_t>(ACLSHMEM_DATA_OP_MTE);
178	#if defined(ACLSHMEM_SOC_950)
179	    constexpr uint32_t supported_engines = mte_engine | static_cast<uint32_t>(ACLSHMEM_DATA_OP_UDMA);
180	#else
181	    constexpr uint32_t supported_engines = mte_engine;
182	#endif
183	    const uint32_t requested_engines = static_cast<uint32_t>(engine);
184	    return requested_engines != 0 && (requested_engines & ~supported_engines) == 0;
185	}
186	
187	static int32_t check_common_attr(aclshmemx_init_attr_t* attributes)
188	{
189	    SHM_LOG_DEBUG(
190	        "check_attr my_pe=" << attributes->my_pe << " n_pes=" << attributes->n_pes
191	                            << " local_mem_size=" << attributes->local_mem_size
192	                            << " shm_init_timeout=" << attributes->option_attr.shm_init_timeout
193	                            << " control_operation_timeout=" << attributes->option_attr.control_operation_timeout);
194	    SHM_VALIDATE_RETURN(attributes->my_pe >= 0, "my_pe is less than zero", ACLSHMEM_INVALID_VALUE);
195	    SHM_VALIDATE_RETURN(attributes->n_pes > 0, "n_pes is less than or equal to zero", ACLSHMEM_INVALID_VALUE);
196	    SHM_VALIDATE_RETURN(attributes->n_pes <= ACLSHMEM_MAX_PES, "n_pes is too large", ACLSHMEM_INVALID_VALUE);
197	    SHM_VALIDATE_RETURN(
198	        attributes->my_pe < attributes->n_pes, "my_pe is greater than or equal to n_pes", ACLSHMEM_INVALID_PARAM);
199	    SHM_VALIDATE_RETURN(
200	        attributes->option_attr.shm_init_timeout != 0, "shm_init_timeout is zero", ACLSHMEM_INVALID_VALUE);
201	    SHM_VALIDATE_RETURN(
202	        attributes->option_attr.control_operation_timeout != 0, "control_operation_timeout is zero",
203	        ACLSHMEM_INVALID_VALUE);
204	    SHM_VALIDATE_RETURN(
205	        attributes->option_attr.data_op_engine_type > 0, "data_op_engine_type is invalid", ACLSHMEM_INVALID_VALUE);
206	    SHM_ASSERT_RETURN(
207	        is_valid_data_op_engine_type(attributes->option_attr.data_op_engine_type), ACLSHMEM_INVALID_VALUE);
208	    return ACLSHMEM_SUCCESS;
209	}
210	
211	int32_t check_attr(aclshmemx_init_attr_t* attributes)
212	{
213	    ACLSHMEM_CHECK_RET(check_common_attr(attributes));
214	    SHM_VALIDATE_RETURN(
215	        attributes->local_mem_size > 0, "local_mem_size less than or equal to 0", ACLSHMEM_INVALID_VALUE);
216	    SHM_ASSERT_RETURN(attributes->local_mem_size <= ACLSHMEM_MAX_LOCAL_SIZE, ACLSHMEM_INVALID_VALUE);
217	    return ACLSHMEM_SUCCESS;
218	}
219	
220	static int32_t check_user_buffer_heap_attr(aclshmemx_init_attr_t* attributes)
221	{
222	    ACLSHMEM_CHECK_RET(check_common_attr(attributes));
223	    SHM_ASSERT_RETURN(attributes->local_mem_size <= ACLSHMEM_MAX_LOCAL_SIZE, ACLSHMEM_INVALID_VALUE);
224	    SHM_ASSERT_RETURN(attributes->local_mem_size % ACLSHMEM_PAGE_SIZE == 0, ACLSHMEM_INVALID_PARAM);
225	    SHM_ASSERT_RETURN(
226	        aclshmemi_user_buffer_heap_engine_supported(attributes->option_attr.data_op_engine_type),
227	        ACLSHMEM_NOT_SUPPORTED);
228	    return ACLSHMEM_SUCCESS;
229	}
230	
231	static bool checked_add_u64(uint64_t lhs, uint64_t rhs, uint64_t* result)
232	{
233	    if (result == nullptr || lhs > std::numeric_limits<uint64_t>::max() - rhs) {
234	        return false;
235	    }
236	    *result = lhs + rhs;
237	    return true;
238	}
239	
240	static bool checked_mul_size(size_t lhs, size_t rhs, size_t* result)
241	{
242	    if (result == nullptr || (rhs != 0 && lhs > std::numeric_limits<size_t>::max() / rhs)) {
243	        return false;
244	    }
245	    *result = lhs * rhs;
246	    return true;
247	}
248	
249	shm::UserBufferHeapInput::~UserBufferHeapInput()
250	{
251	#ifdef HAS_ACLRT_MEM_FABRIC_HANDLE
252	    for (auto& entry : entries) {
253	        if (entry.handle_ownership != shm::UserBufferHandleOwnership::RETAINED || entry.mem_handle == nullptr) {
254	            continue;
255	        }
256	        const auto ret = aclrtFreePhysical(entry.mem_handle);
257	        if (ret != ACL_SUCCESS) {
258	            SHM_LOG_WARN("Failed to release retained buffer allocation handle, ret=" << ret);
259	        }
260	        entry.mem_handle = nullptr;
261	    }
262	#endif
263	}
264	
265	#ifdef HAS_ACLRT_MEM_FABRIC_HANDLE
266	static bool reserved_fields_are_zero(const uint64_t* reserved, size_t count)
267	{
268	    return reserved != nullptr && std::all_of(reserved, reserved + count, [](uint64_t value) { return value == 0; });
269	}
270	
271	static int32_t query_buffer_property(
272	    aclrtDrvMemHandle mem_handle, int32_t current_device, size_t index, aclrtPhysicalMemProp* property)
273	{
274	    SHM_ASSERT_RETURN(mem_handle != nullptr && property != nullptr, ACLSHMEM_INVALID_PARAM);
275	    auto acl_status = shm::DlAclApi::AclrtMemGetAllocationPropertiesFromHandle(mem_handle, property);
276	    if (acl_status == ACLSHMEM_UNDER_API_UNLOAD || acl_status == ACL_ERROR_RT_FEATURE_NOT_SUPPORT) {
277	        property->handleType = ACL_MEM_HANDLE_TYPE_NONE;
278	        property->allocationType = ACL_MEM_ALLOCATION_TYPE_PINNED;
279	        property->location.type = ACL_MEM_LOCATION_TYPE_DEVICE;
280	        property->location.id = current_device;
281	        property->memAttr = ACL_HBM_MEM_HUGE;
282	        property->reserve = 0;
283	        SHM_LOG_WARN(
284	            "Physical allocation property query is not supported; deferring buffer "
285	            << index << " handle validation to export/map");
286	    } else if (acl_status != ACL_SUCCESS) {
287	        SHM_LOG_ERROR(
288	            "aclrtMemGetAllocationPropertiesFromHandle failed for buffer " << index << ", ret=" << acl_status);
289	        return ACLSHMEM_NOT_SUPPORTED;
290	    }
291	    if (property->handleType != ACL_MEM_HANDLE_TYPE_NONE ||
292	        property->allocationType != ACL_MEM_ALLOCATION_TYPE_PINNED ||
293	        property->location.type != ACL_MEM_LOCATION_TYPE_DEVICE || property->location.id != current_device ||
294	        property->memAttr != ACL_HBM_MEM_HUGE) {
295	        SHM_LOG_ERROR(
296	            "Unsupported physical allocation properties for buffer "
297	            << index << ": handleType=" << static_cast<int>(property->handleType)
298	            << ", allocationType=" << static_cast<int>(property->allocationType) << ", locationType="
299	            << static_cast<int>(property->location.type) << ", locationId=" << property->location.id
300	            << ", currentDevice=" << current_device << ", memAttr=" << static_cast<int>(property->memAttr));
301	        return ACLSHMEM_NOT_SUPPORTED;
302	    }
303	    return ACLSHMEM_SUCCESS;
304	}
305	
306	static int32_t validate_user_buffer_metadata(size_t buffer_count, int32_t npes)
307	{
308	    if (buffer_count == 0 || buffer_count > shm::kMaxBuffers || npes <= 0) {
309	        return ACLSHMEM_INVALID_PARAM;
310	    }
311	
312	    size_t metadata_count = 0;
313	    size_t metadata_bytes = 0;
314	    if (buffer_count == std::numeric_limits<size_t>::max() ||
315	        !checked_mul_size(buffer_count + 1, static_cast<size_t>(npes), &metadata_count) ||
316	        !checked_mul_size(metadata_count, sizeof(hybm_exchange_info), &metadata_bytes)) {
317	        return ACLSHMEM_INVALID_VALUE;
318	    }
319	    if (buffer_count + 1 > std::numeric_limits<uint32_t>::max() || metadata_bytes > shm::kMaxBufferMetadataBytes) {
320	        return ACLSHMEM_INVALID_VALUE;
321	    }
322	    return ACLSHMEM_SUCCESS;
323	}
324	
325	static int32_t validate_buffer_descriptor(
326	    const aclshmemx_buffer_desc_t& source, const shm::UserBufferHeapInput& input, size_t index)
327	{
328	    if (source.addr == nullptr || source.size == 0 ||
329	        !reserved_fields_are_zero(source.reserved, sizeof(source.reserved) / sizeof(source.reserved[0])) ||
330	        (source.optional_attr != nullptr &&
331	         !reserved_fields_are_zero(
332	             source.optional_attr->reserved,
333	             sizeof(source.optional_attr->reserved) / sizeof(source.optional_attr->reserved[0])))) {
334	        return ACLSHMEM_INVALID_PARAM;
335	    }
336	
337	    const uintptr_t source_base = reinterpret_cast<uintptr_t>(source.addr);
338	    if (source.size > static_cast<uint64_t>(std::numeric_limits<uintptr_t>::max() - source_base)) {
339	        return ACLSHMEM_INVALID_VALUE;
340	    }
341	    const uintptr_t source_end = source_base + static_cast<uintptr_t>(source.size);
342	    for (size_t previous_index = 0; previous_index < index; ++previous_index) {
343	        const auto& previous = input.entries[previous_index];
344	        const uintptr_t previous_base = reinterpret_cast<uintptr_t>(previous.source_base);
345	        const uintptr_t previous_end = previous_base + static_cast<uintptr_t>(previous.size);
346	        if (source_base < previous_end && previous_base < source_end) {
347	            return ACLSHMEM_INVALID_PARAM;
348	        }
349	    }
350	    return ACLSHMEM_SUCCESS;
351	}
352	
353	static int32_t acquire_buffer_handle(
354	    const aclshmemx_buffer_desc_t& source, int32_t current_device, size_t index, shm::UserBufferHeapInput* input)
355	{
356	    SHM_ASSERT_RETURN(input != nullptr && index < input->entries.size(), ACLSHMEM_INVALID_PARAM);
357	    auto& destination = input->entries[index];
358	    if (source.optional_attr != nullptr && source.optional_attr->mem_handle != nullptr) {
359	        destination.mem_handle = static_cast<aclrtDrvMemHandle>(source.optional_attr->mem_handle);
360	        destination.handle_ownership = shm::UserBufferHandleOwnership::CALLER;
361	    } else {
362	        const auto status = aclrtMemRetainAllocationHandle(source.addr, &destination.mem_handle);
363	        if (status != ACL_SUCCESS || destination.mem_handle == nullptr) {
364	            SHM_LOG_ERROR("aclrtMemRetainAllocationHandle failed for buffer " << index << ", ret=" << status);
365	            return ACLSHMEM_INVALID_PARAM;
366	        }
367	        destination.handle_ownership = shm::UserBufferHandleOwnership::RETAINED;
368	    }
369	    for (size_t previous_index = 0; previous_index < index; ++previous_index) {
370	        if (input->entries[previous_index].mem_handle == destination.mem_handle) {
371	            return ACLSHMEM_INVALID_PARAM;
372	        }
373	    }
374	    return query_buffer_property(destination.mem_handle, current_device, index, &destination.property);
375	}
376	
377	static int32_t validate_buffer_mapping(const aclshmemx_buffer_desc_t& source, size_t index, shm::UserBufferEntry* entry)
378	{
379	    SHM_ASSERT_RETURN(entry != nullptr, ACLSHMEM_INVALID_PARAM);
380	    size_t granularity = 0;
381	    const auto status =
382	        aclrtMemGetAllocationGranularity(&entry->property, ACL_RT_MEM_ALLOC_GRANULARITY_MINIMUM, &granularity);
383	    if (status != ACL_SUCCESS || granularity == 0) {
384	        SHM_LOG_ERROR(
385	            "aclrtMemGetAllocationGranularity failed for buffer " << index << ", ret=" << status
386	                                                                  << ", granularity=" << granularity);
387	        return ACLSHMEM_NOT_SUPPORTED;
388	    }
389	
390	    const uintptr_t source_base = reinterpret_cast<uintptr_t>(source.addr);
391	    if (source_base % granularity != 0 || entry->size % granularity != 0 || entry->segment_offset % granularity != 0) {
392	        SHM_LOG_ERROR(
393	            "Unaligned buffer " << index << ": sourceBase=" << source_base << ", size=" << entry->size
394	                                << ", segmentOffset=" << entry->segment_offset << ", granularity=" << granularity);
395	        return ACLSHMEM_INVALID_PARAM;
396	    }
397	
398	    const auto* optional_attr = source.optional_attr;
399	    entry->has_fabric_handle = optional_attr != nullptr && optional_attr->fabric_handle != nullptr;
400	    if (entry->has_fabric_handle) {
401	        std::memcpy(&entry->fabric_handle, optional_attr->fabric_handle, sizeof(entry->fabric_handle));
402	    }
403	    return ACLSHMEM_SUCCESS;
404	}
