406	static int32_t calculate_user_buffer_layout(
407	    uint64_t external_bytes, uint64_t local_mem_size, uint32_t buffer_count, shm::UserBufferHeapLayoutHeader* header)
408	{
409	    SHM_ASSERT_RETURN(header != nullptr, ACLSHMEM_INVALID_PARAM);
410	    uint64_t user_bytes = 0;
411	    uint64_t owned_bytes = 0;
412	    uint64_t heap_size = 0;
413	    if (!checked_add_u64(external_bytes, local_mem_size, &user_bytes) || user_bytes > ACLSHMEM_MAX_LOCAL_SIZE ||
414	        !checked_add_u64(local_mem_size, ACLSHMEM_EXTRA_SIZE, &owned_bytes) ||
415	        !checked_add_u64(external_bytes, owned_bytes, &heap_size)) {
416	        return ACLSHMEM_INVALID_VALUE;
417	    }
418	    if (heap_size % ACLSHMEM_PAGE_SIZE != 0) {
419	        return ACLSHMEM_INVALID_PARAM;
420	    }
421	
422	    header->buffer_count = buffer_count;
423	    header->external_bytes = external_bytes;
424	    header->allocatable_bytes = local_mem_size;
425	    header->heap_size = heap_size;
426	    return ACLSHMEM_SUCCESS;
427	}
428	
429	static int32_t build_local_layout_header(
430	    const aclshmemx_buffer_desc_t* buffers, size_t buffer_count, const aclshmemx_init_attr_t* attributes,
431	    std::unique_ptr<shm::UserBufferHeapInput>* input, shm::UserBufferHeapLayoutHeader* header)
432	{
433	    SHM_ASSERT_RETURN(attributes != nullptr && input != nullptr && header != nullptr, ACLSHMEM_INVALID_PARAM);
434	    *header = {};
435	    if (buffers == nullptr) {
436	        header->local_status = ACLSHMEM_INVALID_PARAM;
437	        return header->local_status;
438	    }
439	    header->local_status = validate_user_buffer_metadata(buffer_count, attributes->n_pes);
440	    if (header->local_status != ACLSHMEM_SUCCESS) {
441	        return header->local_status;
442	    }
443	
444	    std::unique_ptr<shm::UserBufferHeapInput> local_input;
445	    try {
446	        local_input = std::make_unique<shm::UserBufferHeapInput>();
447	        local_input->entries.resize(buffer_count);
448	    } catch (const std::bad_alloc&) {
449	        header->local_status = ACLSHMEM_MALLOC_FAILED;
450	        return header->local_status;
451	    }
452	
453	    int32_t current_device = -1;
454	    auto acl_status = aclrtGetDevice(&current_device);
455	    if (acl_status != ACL_SUCCESS) {
456	        SHM_LOG_ERROR("aclrtGetDevice failed while normalizing user buffer heap, ret=" << acl_status);
457	        header->local_status = ACLSHMEM_NOT_SUPPORTED;
458	        return header->local_status;
459	    }
460	
461	    uint64_t external_bytes = 0;
462	    for (size_t i = 0; i < buffer_count; ++i) {
463	        const auto& src = buffers[i];
464	        header->local_status = validate_buffer_descriptor(src, *local_input, i);
465	        if (header->local_status != ACLSHMEM_SUCCESS) {
466	            return header->local_status;
467	        }
468	        auto& dst = local_input->entries[i];
469	        dst.source_base = src.addr;
470	        dst.size = src.size;
471	        dst.segment_offset = external_bytes;
472	        header->local_status = acquire_buffer_handle(src, current_device, i, local_input.get());
473	        if (header->local_status == ACLSHMEM_SUCCESS) {
474	            header->local_status = validate_buffer_mapping(src, i, &dst);
475	        }
476	        if (header->local_status != ACLSHMEM_SUCCESS) {
477	            return header->local_status;
478	        }
479	        if (!checked_add_u64(external_bytes, src.size, &external_bytes)) {
480	            header->local_status = ACLSHMEM_INVALID_VALUE;
481	            return header->local_status;
482	        }
483	    }
484	
485	    header->local_status = calculate_user_buffer_layout(
486	        external_bytes, attributes->local_mem_size, static_cast<uint32_t>(buffer_count), header);
487	    if (header->local_status != ACLSHMEM_SUCCESS) {
488	        return header->local_status;
489	    }
490	
491	    *input = std::move(local_input);
492	    return ACLSHMEM_SUCCESS;
493	}
