495	static int32_t validate_layout_headers(const std::vector<shm::UserBufferHeapLayoutHeader>& headers, int32_t npes)
496	{
497	    SHM_ASSERT_RETURN(npes > 0 && headers.size() == static_cast<size_t>(npes), ACLSHMEM_INVALID_PARAM);
498	    for (int32_t pe = 0; pe < npes; ++pe) {
499	        if (headers[pe].local_status != ACLSHMEM_SUCCESS) {
500	            return headers[pe].local_status;
501	        }
502	    }
503	    const auto& expected = headers[0];
504	    for (int32_t pe = 1; pe < npes; ++pe) {
505	        const auto& current = headers[pe];
506	        if (current.buffer_count != expected.buffer_count || current.external_bytes != expected.external_bytes ||
507	            current.allocatable_bytes != expected.allocatable_bytes || current.heap_size != expected.heap_size) {
508	            return ACLSHMEM_INVALID_PARAM;
509	        }
510	    }
511	    return ACLSHMEM_SUCCESS;
512	}
