514	static int32_t validate_size_vectors(
515	    const shm::UserBufferHeapInput& input, int32_t npes, aclshmemi_bootstrap_handle_t* boot_handle)
516	{
517	    SHM_ASSERT_RETURN(boot_handle != nullptr && boot_handle->allgather != nullptr, ACLSHMEM_INVALID_PARAM);
518	    SHM_ASSERT_RETURN(!input.entries.empty(), ACLSHMEM_INVALID_PARAM);
519	    size_t local_bytes = 0;
520	    size_t gathered_count = 0;
521	    if (!checked_mul_size(input.entries.size(), sizeof(uint64_t), &local_bytes) ||
522	        local_bytes > static_cast<size_t>(std::numeric_limits<int>::max()) ||
523	        !checked_mul_size(input.entries.size(), static_cast<size_t>(npes), &gathered_count)) {
524	        return ACLSHMEM_INVALID_VALUE;
525	    }
526	    std::vector<uint64_t> local_sizes;
527	    std::vector<uint64_t> all_sizes;
528	    try {
529	        local_sizes.resize(input.entries.size());
530	        all_sizes.resize(gathered_count);
531	    } catch (const std::bad_alloc&) {
532	        return ACLSHMEM_MALLOC_FAILED;
533	    }
534	    for (size_t i = 0; i < input.entries.size(); ++i) {
535	        local_sizes[i] = input.entries[i].size;
536	    }
537	    ACLSHMEM_CHECK_RET(
538	        boot_handle->allgather(local_sizes.data(), all_sizes.data(), static_cast<int>(local_bytes), boot_handle));
539	    for (int32_t pe = 0; pe < npes; ++pe) {
540	        for (size_t i = 0; i < local_sizes.size(); ++i) {
541	            if (all_sizes[static_cast<size_t>(pe) * local_sizes.size() + i] != local_sizes[i]) {
542	                return ACLSHMEM_INVALID_PARAM;
543	            }
544	        }
545	    }
546	    return ACLSHMEM_SUCCESS;
547	}
