565	
566	    for (int32_t pe = 0; pe < npes; ++pe) {
567	        if (all_status[pe] != ACLSHMEM_SUCCESS) {
568	            return all_status[pe];
569	        }
570	    }
571	    return ACLSHMEM_SUCCESS;
