665	static int32_t aclshmemi_instance_port_selection(aclshmemx_init_attr_t* attributes)
666	{
667	    // 1. Get Port Range From Environment
668	    const char* env_port_range = std::getenv("SHMEM_INSTANCE_PORT_RANGE");
669	    if (env_port_range == nullptr) {
670	        SHM_LOG_ERROR("The environment variable SHMEM_INSTANCE_PORT_RANGE is not set.");
671	        return ACLSHMEM_INVALID_VALUE;
672	    }
673	
674	    std::string env_port_range_str(env_port_range);
675	    std::size_t env_pos = env_port_range_str.find(':');
676	    if (env_pos == std::string::npos) {
677	        SHM_LOG_ERROR("SHMEM_INSTANCE_PORT_RANGE format should be start_port:end_port");
678	        return ACLSHMEM_INVALID_VALUE;
679	    }
680	
681	    uint16_t start_port;
682	    uint16_t end_port;
683	    std::string start_port_str = env_port_range_str.substr(0, env_pos);
684	    std::string end_port_str = env_port_range_str.substr(env_pos + 1, env_port_range_str.size());
685	    if (!aclshmemi_parse_port_strict(start_port_str, start_port)) {
686	        SHM_LOG_ERROR("Invalid start_port value: " << start_port_str << ", must be in range [0, 65535]");
687	        return ACLSHMEM_INVALID_VALUE;
688	    }
689	    if (!aclshmemi_parse_port_strict(end_port_str, end_port)) {
690	        SHM_LOG_ERROR("Invalid end_port value: " << end_port_str << ", must be in range [0, 65535]");
691	        return ACLSHMEM_INVALID_VALUE;
692	    }
693	    if (end_port < start_port) {
694	        SHM_LOG_ERROR("SHMEM_INSTANCE_PORT_RANGE: start_port " << start_port << " exceeds end_port " << end_port);
695	        return ACLSHMEM_INVALID_VALUE;
696	    }
697	
698	    // 2. Check if instance_id is valid
699	    int max_instance_num = end_port - start_port;
700	    uint64_t instance_id = attributes->instance_id;
701	    if (instance_id > static_cast<uint64_t>(max_instance_num)) {
702	        SHM_LOG_ERROR(
703	            "instance_id " << instance_id << " exceeds max_instance_num " << max_instance_num << " in default mode");
704	        return ACLSHMEM_INVALID_VALUE;
705	    }
706	    uint16_t port = start_port + static_cast<uint16_t>(instance_id);
707	
708	    // 3. If ip_port is null, return
709	    if (attributes->ip_port[0] == '\0') {
710	        SHM_LOG_ERROR("init with my_rank:" << attributes->my_pe << " ip_port is nullptr!");
711	        return ACLSHMEM_INVALID_VALUE;
712	    }
713	
714	    // 4. replace ip_port in attributes
715	    std::string ip_port_str(attributes->ip_port);
716	    std::size_t pos;
717	    if (ip_port_str.find("tcp6://") == 0) {
718	        std::size_t bracketEnd = ip_port_str.find(']');
719	        if (bracketEnd == std::string::npos || bracketEnd + 2 >= ip_port_str.size() ||
720	            ip_port_str[bracketEnd + 1] != ':') {
721	            SHM_LOG_ERROR("ip_port format should be tcp6://[ipv6_addr]:port");
722	            return ACLSHMEM_INVALID_VALUE;
723	        }
724	        pos = bracketEnd + 1;
725	    } else {
726	        pos = ip_port_str.find(':', ip_port_str.find(':') + 1);
727	    }
728	    if (pos == std::string::npos) {
729	        SHM_LOG_ERROR("ip_port format should be ip:port");
730	        return ACLSHMEM_INVALID_VALUE;
731	    }
732	
733	    uint16_t input_port;
734	    std::string input_port_str = ip_port_str.substr(pos + 1, ip_port_str.size());
735	    if (!aclshmemi_parse_port_strict(input_port_str, input_port)) {
736	        SHM_LOG_ERROR("Invalid input_port value: " << input_port_str << ", must be in range [0, 65535]");
737	        return ACLSHMEM_INVALID_VALUE;
738	    }
739	    if (input_port != 0) {
740	        SHM_LOG_ERROR("input_port must be 0 in default mode, but input_port is " << input_port);
741	        return ACLSHMEM_INVALID_VALUE;
742	    }
743	
744	    std::string instance_ipport = ip_port_str.substr(0, pos) + ":" + std::to_string(port);
745	    if (instance_ipport.empty()) {
746	        SHM_LOG_ERROR("my_rank:" << attributes->my_pe << " instance ipport is nullptr!");
747	        return ACLSHMEM_INVALID_VALUE;
748	    }
749	
750	    // 5. Write port in attributes
751	    size_t ipport_len = std::min(instance_ipport.size(), static_cast<std::size_t>(ACLSHMEM_MAX_IP_PORT_LEN - 1));
752	    std::copy_n(instance_ipport.c_str(), ipport_len, attributes->ip_port);
753	    attributes->ip_port[ipport_len] = '\0';
754	
755	    return ACLSHMEM_SUCCESS;
756	}
