758	static int aclshmemi_instance_ctx_create(aclshmemx_init_attr_t* attributes)
759	{
760	    uint64_t instance_id = attributes->instance_id;
761	    if (instance_id == 0) {
762	        // Do Nothing.
763	        return ACLSHMEM_SUCCESS;
764	    }
765	
766	    // Check if Repeat
767	    if (aclshmem_ctx_domain.find(instance_id) != aclshmem_ctx_domain.end() ||
768	        aclshmem_resource_domain.find(instance_id) != aclshmem_resource_domain.end()) {
769	        SHM_LOG_WARN("Instance " << instance_id << " already exists ! Please don't repeat create !");
770	        return ACLSHMEM_SUCCESS;
771	    }
772	
773	    // aclshmem_instance port selection, if init with uid, skip
774	    if (attributes->ip_port[0] != '\0' || attributes->comm_args == nullptr) {
775	        ACLSHMEM_CHECK_RET(aclshmemi_instance_port_selection(attributes));
776	    }
777	
778	    // Create aclshmem_instance_ctx
779	    aclshmem_instance_ctx* aclshmem_ctx = new (std::nothrow) aclshmem_instance_ctx{attributes->instance_id, nullptr};
780	    if (aclshmem_ctx == nullptr) {
781	        SHM_LOG_ERROR("Failed to allocate memory for aclshmem_instance_ctx.");
782	        return ACLSHMEM_INNER_ERROR;
783	    }
784	    aclshmem_ctx_domain[attributes->instance_id] = aclshmem_ctx;
785	
786	    aclshmem_context* aclshmem_resource_ctx = new (std::nothrow) aclshmem_context(attributes->instance_id);
787	    if (aclshmem_resource_ctx == nullptr) {
788	        SHM_LOG_ERROR("Failed to allocate memory for aclshmem_context.");
789	        aclshmem_ctx_domain.erase(attributes->instance_id);
790	        delete aclshmem_ctx;
791	        return ACLSHMEM_INNER_ERROR;
792	    }
793	    aclshmem_resource_domain[attributes->instance_id] = aclshmem_resource_ctx;
794	
795	    SHM_LOG_INFO(
796	        "PE: " << attributes->my_pe << " USING SHMEM Multi-Instance Mode ! Now Ctx set to Instance " << instance_id
797	               << " !");
798	    return ACLSHMEM_SUCCESS;
799	}
