801	static int aclshmemi_instance_ctx_destroy(uint64_t instance_id)
802	{
803	    if (instance_id == 0) {
804	        // Do Nothing.
805	        return ACLSHMEM_SUCCESS;
806	    }
807	
808	    // if destroy an active context
809	    if (instance_id == g_instance_ctx->id) {
810	        // Set active context to Instance 0
811	        aclshmemx_instance_ctx_set_impl(0);
812	    }
813	
814	    // Release Resource
815	    auto it_resource = aclshmem_resource_domain.find(instance_id);
816	    if (it_resource == aclshmem_resource_domain.end()) {
817	        SHM_LOG_ERROR("Instance " << instance_id << " not exists! Illegal Context Destroy!");
818	        return ACLSHMEM_INNER_ERROR;
819	    }
820	    delete it_resource->second;
821	    aclshmem_resource_domain.erase(it_resource);
822	
823	    auto it_ctx = aclshmem_ctx_domain.find(instance_id);
824	    if (it_ctx == aclshmem_ctx_domain.end()) {
825	        SHM_LOG_ERROR("Instance " << instance_id << " not exists! Illegal Context Destroy!");
826	        return ACLSHMEM_INNER_ERROR;
827	    }
828	    delete it_ctx->second;
829	    aclshmem_ctx_domain.erase(it_ctx);
830	
831	    return ACLSHMEM_SUCCESS;
832	}
