846	// Inner Context set Interface, No Lock.
847	int aclshmemx_instance_ctx_set_impl(uint64_t instance_id)
848	{
849	    if (aclshmem_ctx_domain.find(instance_id) != aclshmem_ctx_domain.end()) {
850	        aclshmem_instance_ctx* new_ctx = aclshmem_ctx_domain[instance_id];
851	        aclshmem_context* new_context = aclshmem_resource_domain[instance_id];
852	        aclshmem_context* current_context = aclshmem_resource_domain[g_instance_ctx->id];
853	
854	        // Global_vars write back
855	        current_context->state = g_state;
856	        current_context->host_state = g_state_host;
857	        current_context->bootstrap_plugin_hdl = plugin_hdl;
858	        current_context->boot_handle = g_boot_handle;
859	        current_context->dev_mem_manager = aclshmemi_memory_manager;
860	        current_context->host_mem_manager = aclshmemi_host_memory_manager;
861	        aclshmemi_exception_report_save_context(current_context->exception_report_context);
862	
863	        // Set Global_vars by new_context
864	        g_state = new_context->state;
865	        g_state_host = new_context->host_state;
866	        plugin_hdl = new_context->bootstrap_plugin_hdl;
867	        g_boot_handle = new_context->boot_handle;
868	        aclshmemi_memory_manager = new_context->dev_mem_manager;
869	        aclshmemi_host_memory_manager = new_context->host_mem_manager;
870	        aclshmemi_exception_report_restore_context(new_context->exception_report_context);
871	
872	        // Set New aclshmem context
873	        g_instance_ctx = aclshmem_ctx_domain[instance_id];
874	
875	        return ACLSHMEM_SUCCESS;
876	    }
877	    SHM_LOG_ERROR("Context Set failed ! Can't find instance " << instance_id << " !");
878	    return ACLSHMEM_INNER_ERROR;
879	}
