886	static int32_t aclshmemi_init_attr_impl(
887	    aclshmemx_bootstrap_t bootstrap_flags, aclshmemx_init_attr_t* attributes, InitHeapMode heap_mode,
888	    const void* buffer_descs, size_t buffer_count)
889	{
890	    std::lock_guard<std::mutex> lock(g_aclshmem_ctx_mutex);
891	    SHM_ASSERT_RETURN(attributes != nullptr, ACLSHMEM_INVALID_PARAM);
892	    const bool use_user_buffer_heap = heap_mode == InitHeapMode::USER_BUFFER_HEAP;
893	    int32_t ret;
894	    uint64_t id = attributes->instance_id;
895	
896	    // Multi-instance create ctx. Only install rollback for newly created
897	    // instances — re-init of an existing instance must not destroy it on failure.
898	    bool is_new_instance = (id != 0 && aclshmem_ctx_domain.find(id) == aclshmem_ctx_domain.end());
899	    ACLSHMEM_CHECK_RET(aclshmemi_instance_ctx_create(attributes));
900	    auto ctx_guard = shm::utils::make_scope_guard(static_cast<void*>(nullptr), [id, is_new_instance](void*) {
901	        if (is_new_instance) {
902	            (void)aclshmemi_instance_ctx_destroy(id);
903	        }
904	    });
905	    ACLSHMEM_CHECK_RET(aclshmemx_instance_ctx_set_impl(id));
906	
907	    bool init_succeeded = false;
908	    bool bootstrap_initialized = false;
909	    bool backend_counted = false;
910	    bool entity_bound = false;
911	    bool device_state_initialized = false;
912	    bool heap_reserved = false;
913	    auto init_abort_guard = shm::utils::make_scope_guard(static_cast<void*>(nullptr), [&](void*) {
914	        if (init_succeeded) {
915	            return;
916	        }
917	
918	        SHM_LOG_WARN("ACL SHMEM initialization failed; releasing partial resources without synchronization.");
919	        memory_manager_destroy();
920	        if (init_manager != nullptr && entity_bound) {
921	            if (heap_reserved) {
922	                (void)init_manager->remove_heap();
923	            }
924	            (void)init_manager->release_heap();
925	            if (device_state_initialized) {
926	                (void)init_manager->finalize_device_state();
927	            }
928	            (void)init_manager->release_aclshmem_entity(id);
929	        }
930	        if (bootstrap_initialized) {
931	            aclshmemi_bootstrap_finalize();
932	        }
933	        if (backend_counted) {
934	            --g_init_manager_count;
935	            if (g_init_manager_count == 0) {
936	                delete init_manager;
937	                init_manager = nullptr;
938	            }
939	        }
940	        g_state.is_aclshmem_initialized = false;
941	    });
942	
943	    // config init
944	    ACLSHMEM_CHECK_RET(
945	        aclshmemx_init_status() != ACLSHMEM_STATUS_NOT_INITIALIZED,
946	        "SHMEM has been initialized, do not call init interface repeatedly!", ACLSHMEM_INNER_ERROR);
947	    ACLSHMEM_CHECK_RET(aclshmemx_set_log_level(aclshmem_log::ERROR_LEVEL));
948	    ACLSHMEM_CHECK_RET(
949	        use_user_buffer_heap ? check_user_buffer_heap_attr(attributes) : check_attr(attributes),
950	        "An error occurred while checking the initialization attributes. Please check the initialization parameters.");
951	    ACLSHMEM_CHECK_RET(version_compatible(), "ACLSHMEM Version mismatch.");
952	
953	    // init bootstrap
954	    ACLSHMEM_CHECK_RET(aclshmemi_bootstrap_init(bootstrap_flags, attributes));
955	    bootstrap_initialized = true;
956	
957	    uint64_t heap_size = attributes->local_mem_size + ACLSHMEM_EXTRA_SIZE;
958	    uint64_t external_bytes = 0;
959	    std::unique_ptr<shm::UserBufferHeapInput> user_buffer_heap_input;
960	    if (use_user_buffer_heap) {
961	#ifdef HAS_ACLRT_MEM_FABRIC_HANDLE
962	        const auto* buffers = static_cast<const aclshmemx_buffer_desc_t*>(buffer_descs);
963	        shm::UserBufferHeapLayoutHeader local_header{};
964	        (void)build_local_layout_header(buffers, buffer_count, attributes, &user_buffer_heap_input, &local_header);
965	        std::vector<shm::UserBufferHeapLayoutHeader> all_headers;
966	        try {
967	            all_headers.resize(static_cast<size_t>(attributes->n_pes));
968	        } catch (const std::bad_alloc&) {
969	            return ACLSHMEM_MALLOC_FAILED;
970	        }
971	        ACLSHMEM_CHECK_RET(g_boot_handle.allgather(
972	            &local_header, all_headers.data(), static_cast<int>(sizeof(local_header)), &g_boot_handle));
973	        ACLSHMEM_CHECK_RET(validate_layout_headers(all_headers, attributes->n_pes));
974	        SHM_ASSERT_RETURN(user_buffer_heap_input != nullptr, ACLSHMEM_INNER_ERROR);
975	        ACLSHMEM_CHECK_RET(validate_size_vectors(*user_buffer_heap_input, attributes->n_pes, &g_boot_handle));
976	        external_bytes = local_header.external_bytes;
977	        heap_size = local_header.heap_size;
978	#else
979	        return ACLSHMEM_NOT_SUPPORTED;
980	#endif
981	    }
982	    ACLSHMEM_CHECK_RET(aclshmemi_state_init_attr(attributes, heap_size));
983	
984	    // init backend for memory manager
985	    g_init_manager_count++;
986	    backend_counted = true;
987	    if (init_manager == nullptr) {
988	        init_manager = new aclshmemi_init_backend();
989	    } else {
990	        SHM_LOG_INFO("init_manager already exists, skipping creation. ");
991	    }
992	
993	    // aclshmem_entity init
994	    ACLSHMEM_CHECK_RET(init_manager->bind_aclshmem_entity(
995	        attributes, &g_state, &g_boot_handle, std::move(user_buffer_heap_input), g_udma_qp_config));
996	    entity_bound = true;
997	    ACLSHMEM_CHECK_RET(init_manager->init_device_state());
998	    device_state_initialized = true;
999	    auto exception_guard =
1000	        shm::utils::make_scope_guard(static_cast<void*>(nullptr), [](void*) { aclshmemi_exception_report_finalize(); });
1001	    ACLSHMEM_CHECK_RET(aclshmemi_exception_report_apply_deferred_config(attributes->option_attr.data_op_engine_type));
1002	    int32_t reserve_status = init_manager->reserve_heap();
1003	    if (use_user_buffer_heap) {
1004	        ACLSHMEM_CHECK_RET(aclshmemi_collective_status_gate(reserve_status, attributes->n_pes, &g_boot_handle));
1005	    } else {
1006	        ACLSHMEM_CHECK_RET(reserve_status);
1007	    }
1008	    heap_reserved = true;
1009	    ACLSHMEM_CHECK_RET(init_manager->setup_heap());
1010	
1011	    // shmem submodules init
1012	    auto* allocator_base = static_cast<uint8_t*>(g_state.heap_base) + external_bytes;
1013	    ACLSHMEM_CHECK_RET(memory_manager_initialize(allocator_base, g_state.heap_size - external_bytes));
1014	
1015	    if (check_support_d2h()) {
1016	        // only reserve dramp heap, skip setup_heap for host dram, setup heap when malloc on host
1017	        ACLSHMEM_CHECK_RET(init_manager->reserve_heap(HOST_SIDE));
1018	    }
1019	    ACLSHMEM_CHECK_RET(aclshmemi_signal_init());
1020	    ACLSHMEM_CHECK_RET(aclshmemi_team_init(g_state.mype, g_state.npes));
1021	    ACLSHMEM_CHECK_RET(aclshmemi_sync_init());
1022	    g_state.is_aclshmem_initialized = true;
1023	    ACLSHMEM_CHECK_RET(prof_util_init(&g_host_profs, &g_state));
1024	    ACLSHMEM_CHECK_RET(update_device_state());
1025	    ACLSHMEM_CHECK_RET(aclshmemi_control_barrier_all());
1026	    SHM_LOG_INFO("The ACLSHMEM pe: " << aclshmem_my_pe() << " init success.");
1027	    exception_guard.release();
1028	    init_succeeded = true;
1029	    g_qp_config_frozen = true;
1030	    init_abort_guard.release();
1031	    ctx_guard.release();
1032	    return ACLSHMEM_SUCCESS;
1033	}
