1056	static int32_t aclshmemi_finalize_impl(uint64_t instance_id)
1057	{
1058	    // Only switch context when finalizing a non-active instance; finalizing the
1059	    // currently active instance needs no switch (globals already hold its state).
1060	    // set_impl also validates that instance_id exists, preventing accidental
1061	    // release of the active instance when an unknown id is passed.
1062	    if (instance_id != g_instance_ctx->id) {
1063	        ACLSHMEM_CHECK_RET(aclshmemx_instance_ctx_set_impl(instance_id));
1064	    }
1065	
1066	    SHM_LOG_INFO("The instance : " << instance_id << ", The pe: " << aclshmem_my_pe() << " begins to finalize.");
1067	    if (init_manager == nullptr) {
1068	        SHM_LOG_INFO("init_manager is null finalize success.");
1069	        g_state.is_aclshmem_initialized = false;
1070	        ACLSHMEM_CHECK_RET(aclshmemi_instance_ctx_destroy(instance_id));
1071	        return ACLSHMEM_SUCCESS;
1072	    }
1073	
1074	    if (g_init_manager_count == 1) {
1075	        aclshmemi_exception_report_finalize();
1076	    }
1077	
1078	    ACLSHMEM_CHECK_RET(aclshmemi_control_barrier_all());
1079	
1080	    // shmem submodules finalize
1081	    ACLSHMEM_CHECK_RET(aclshmemi_team_finalize());
1082	    ACLSHMEM_CHECK_RET(aclshmemi_signal_finalize());
1083	    memory_manager_destroy();
1084	
1085	    // From this point onward the runtime submodules are no longer usable.  Keep
1086	    // is_aclshmem_created set until every destructive heap-cleanup step has
1087	    // completed, so a cleanup failure is reported as SHM_CREATED rather than as
1088	    // a fully initialized (or fully finalized) instance.
1089	    g_state.is_aclshmem_initialized = false;
1090	
1091	    int32_t firstCleanupStatus = ACLSHMEM_SUCCESS;
1092	    auto recordCleanupStatus = [&](int32_t status, const char* operation) {
1093	        if (status == ACLSHMEM_SUCCESS) {
1094	            return;
1095	        }
1096	        SHM_LOG_ERROR(operation << " failed during finalize, ret=" << status);
1097	        if (firstCleanupStatus == ACLSHMEM_SUCCESS) {
1098	            firstCleanupStatus = status;
1099	        }
1100	    };
1101	
1102	    // shmem basic finalize
1103	    const int32_t removeStatus = init_manager->remove_heap();
1104	    recordCleanupStatus(removeStatus, "remove_heap");
1105	    recordCleanupStatus(
1106	        aclshmemi_collective_status_gate(removeStatus, g_state.npes, &g_boot_handle),
1107	        "collective remove_heap status gate");
1108	    recordCleanupStatus(init_manager->release_heap(), "release_heap");
1109	    recordCleanupStatus(init_manager->finalize_device_state(), "finalize_device_state");
1110	    if (check_support_d2h()) {
1111	        recordCleanupStatus(init_manager->remove_heap(HOST_SIDE), "remove host heap");
1112	        recordCleanupStatus(init_manager->release_heap(HOST_SIDE), "release host heap");
1113	    }
1114	    recordCleanupStatus(init_manager->release_aclshmem_entity(instance_id), "release ACLSHMEM entity");
1115	    if (g_state_host.default_stream != nullptr) {
1116	        auto ret = aclrtSynchronizeStream(g_state_host.default_stream);
1117	        recordCleanupStatus(ret, "synchronize default stream");
1118	        ret = aclrtDestroyStream(g_state_host.default_stream);
1119	        recordCleanupStatus(ret, "destroy default stream");
1120	        g_state_host.default_stream = nullptr;
1121	    }
1122	
1123	    // Synchronize all ranks before destroying the store, so that no rank
1124	    // can start the next init while another rank's store is still alive.
1125	    recordCleanupStatus(aclshmemi_control_barrier_all(), "finalize control barrier");
1126	    aclshmemi_bootstrap_finalize();
1127	
1128	    // Only when the process has no instance, release init_manager.
1129	    g_init_manager_count--;
1130	    const bool is_last_instance = (g_init_manager_count == 0);
1131	    if (is_last_instance) {
1132	        delete init_manager;
1133	        init_manager = nullptr;
1134	    }
1135	    if (firstCleanupStatus == ACLSHMEM_SUCCESS) {
1136	        SHM_LOG_INFO("The pe: " << aclshmem_my_pe() << " finalize success.");
1137	    } else {
1138	        SHM_LOG_ERROR(
1139	            "The pe: " << aclshmem_my_pe() << " completed finalize cleanup with error: " << firstCleanupStatus);
1140	    }
1141	    g_state.is_aclshmem_initialized = false;
1142	    recordCleanupStatus(aclshmemi_instance_ctx_destroy(instance_id), "destroy instance context");
1143	    if (is_last_instance) {
1144	        g_udma_qp_config = shm::transport::UdmaQpConfig{};
1145	        g_qp_config_frozen = false;
1146	    }
1147	    return firstCleanupStatus;
1148	}
1149	
1150	int32_t aclshmemx_finalize(uint64_t instance_id)
1151	{
1152	    SHM_LOG_INFO("aclshmemx_finalize called with instance_id=" << instance_id);
1153	    std::lock_guard<std::mutex> lock(g_aclshmem_ctx_mutex);
1154	    return aclshmemi_finalize_impl(instance_id);
1155	}
